using System.Collections.Generic;using System.Linq;using UnityEngine;
namespace Echo.Manor.Editor {
 // Subtract window rectangles from existing triangle faces while interpolating the original atlas UVs.
 internal static class WindowWallCut {
  private struct V {public Vector3 p;public Vector2 uv;public V(Vector3 p,Vector2 uv){this.p=p;this.uv=uv;}}
  private static List<V> Clip(List<V> polygon,int axis,float edge,bool less){var output=new List<V>();if(polygon.Count==0)return output;var a=polygon[polygon.Count-1];bool insideA=less?a.p[axis]<=edge:a.p[axis]>=edge;foreach(var b in polygon){bool insideB=less?b.p[axis]<=edge:b.p[axis]>=edge;if(insideA!=insideB){float t=(edge-a.p[axis])/(b.p[axis]-a.p[axis]);output.Add(new V(Vector3.Lerp(a.p,b.p,t),Vector2.Lerp(a.uv,b.uv,t)));}if(insideB)output.Add(b);a=b;insideA=insideB;}return output;}
  public static Mesh Cut(Mesh source,Transform transform,Rect[] holes){var vertices=new List<Vector3>();var uv=new List<Vector2>();var indices=new List<int>();var old=source.vertices;var oldUV=source.uv;var triangles=source.triangles;for(int i=0;i<triangles.Length;i+=3){var list=new List<List<V>>{new List<V>{new V(transform.TransformPoint(old[triangles[i]]),oldUV[triangles[i]]),new V(transform.TransformPoint(old[triangles[i+1]]),oldUV[triangles[i+1]]),new V(transform.TransformPoint(old[triangles[i+2]]),oldUV[triangles[i+2]])}};foreach(var hole in holes){var next=new List<List<V>>();foreach(var poly in list){if(poly.Any(v=>Mathf.Abs(v.p.z+12)>.111f)){next.Add(poly);continue;}var remain=poly;foreach(var cut in new[]{new Vector3(0,hole.xMin,1),new Vector3(0,hole.xMax,0),new Vector3(1,hole.yMin,1),new Vector3(1,hole.yMax,0)}){var outside=Clip(remain,(int)cut.x,cut.y,cut.z>0);if(outside.Count>=3)next.Add(outside);remain=Clip(remain,(int)cut.x,cut.y,cut.z==0);} }list=next;}foreach(var poly in list){int n=vertices.Count;foreach(var v in poly){vertices.Add(transform.InverseTransformPoint(v.p));uv.Add(v.uv);}for(int j=1;j<poly.Count-1;j++)indices.AddRange(new[]{n,n+j,n+j+1});}}
   var mesh=new Mesh{name=source.name+" with gallery apertures"};mesh.indexFormat=UnityEngine.Rendering.IndexFormat.UInt32;mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(indices,0);mesh.RecalculateNormals();mesh.RecalculateBounds();return mesh;}
 }
}
